// Get publishing prompts from cache and select appropriate format
const promptSelector = require('/home/node/.n8n/custom/functions/promptSelector.js');
const prompts = global.prompts || {};

// Extract parameters
const platform = items[0].json.platform || 'twitter';
const content = items[0].json.generated_content || items[0].json.content || '';
const mediaUrl = items[0].json.media_url || null;
const videoUrl = items[0].json.video_url || null;
const hashtags = items[0].json.hashtags || [];

// Variables for template replacement
const variables = {
  CONTENT: content,
  CAPTION: content.substring(0, 150),
  HOOK: content.split('.')[0] || content.substring(0, 50),
  HASHTAGS: hashtags.map(tag => tag.startsWith('#') ? tag : `#${tag}`).join(' '),
  CTA: items[0].json.cta || 'What do you think?',
  QUESTION: items[0].json.question || 'Share your thoughts below!',
  TITLE: items[0].json.title || content.substring(0, 100),
  DESCRIPTION: items[0].json.description || content,
  HEADLINE: items[0].json.headline || content.split('.')[0],
  INDUSTRY: items[0].json.industry || 'business',
  NICHE: items[0].json.niche || 'general'
};

// Get publishing format
let publishConfig;
try {
  publishConfig = promptSelector.select('Publishing_Prompts', platform, 'post', {
    prompts,
    variables
  });
} catch (error) {
  // Fallback format
  publishConfig = {
    platform: platform,
    formatTemplate: '{CONTENT}',
    mediaRequirements: [],
    qualityChecks: ['length_check'],
    platformLimits: {}
  };
}

// Apply platform limits
let formattedContent = publishConfig.formatTemplate || content;

// Check character limits
if (publishConfig.platformLimits.caption) {
  const limit = publishConfig.platformLimits.caption.value;
  if (formattedContent.length > limit) {
    formattedContent = formattedContent.substring(0, limit - 3) + '...';
  }
}

return [{
  json: {
    ...items[0].json,
    publish_config: publishConfig,
    formatted_content: formattedContent,
    media_requirements: publishConfig.mediaRequirements,
    quality_checks: publishConfig.qualityChecks,
    needs_media: publishConfig.mediaRequirements.length > 0 && !mediaUrl && !videoUrl
  }
}];

// Run quality checks based on platform requirements
const platform = items[0].json.platform;
const content = items[0].json.formatted_content;
const checks = items[0].json.quality_checks || [];
const limits = items[0].json.publish_config.platformLimits || {};

const issues = [];
let score = 100;

// Platform-specific checks
checks.forEach(check => {
  switch (check) {
    case 'hook_in_3s':
      // Check if first sentence is compelling
      const firstSentence = content.split('.')[0];
      if (firstSentence.length > 50) {
        issues.push('Hook too long - aim for under 50 characters');
        score -= 10;
      }
      break;

    case 'captions_burned':
      // Check if video has captions
      if (items[0].json.video && !items[0].json.has_captions) {
        issues.push('Video needs burned-in captions for accessibility');
        score -= 15;
      }
      break;

    case 'first_line_impact':
      // Check if first line grabs attention
      const firstLine = content.split('\n')[0];
      if (firstLine.length < 10 || !firstLine.match(/[!?]|\b(you|your|discover|revealed|secret)\b/i)) {
        issues.push('First line needs more impact - use questions or power words');
        score -= 10;
      }
      break;

    case 'emoji_spacing':
      // Check emoji usage
      const emojiCount = (content.match(/[\u{1F300}-\u{1F9FF}]/gu) || []).length;
      if (platform === 'instagram' && emojiCount < 2) {
        issues.push('Add more emojis for Instagram engagement');
        score -= 5;
      }
      break;

    case 'professional_tone':
      // Check for professional language
      const casualWords = ['gonna', 'wanna', 'lol', 'omg', 'btw'];
      const hasCasual = casualWords.some(word => content.toLowerCase().includes(word));
      if (hasCasual) {
        issues.push('Use more professional language for LinkedIn');
        score -= 15;
      }
      break;

    case 'no_clickbait':
      // Check for clickbait patterns
      const clickbaitPatterns = ['you won\'t believe', 'shocking', 'mind-blowing', 'number [0-9] will'];
      const hasClickbait = clickbaitPatterns.some(pattern => 
        content.toLowerCase().match(new RegExp(pattern))
      );
      if (hasClickbait) {
        issues.push('Avoid clickbait language on professional platforms');
        score -= 20;
      }
      break;

    case 'under_250_chars':
      if (content.length > 250) {
        issues.push(`Content too long: ${content.length} chars (max 250)`);
        score -= 10;
      }
      break;

    case 'natural_language':
      // Check for natural flow
      const hashtagCount = (content.match(/#/g) || []).length;
      if (hashtagCount > 5) {
        issues.push('Too many hashtags - keep it natural');
        score -= 5;
      }
      break;

    case 'engagement_focused':
      // Check for engagement elements
      if (!content.includes('?') && !content.match(/what|how|why|share|comment/i)) {
        issues.push('Add a question or call-to-action for engagement');
        score -= 10;
      }
      break;

    case 'authentic':
      // Check for overly promotional language
      const promoWords = ['buy now', 'limited time', 'discount', 'sale', 'offer'];
      const hasPromo = promoWords.some(word => content.toLowerCase().includes(word));
      if (hasPromo && !items[0].json.is_promotional) {
        issues.push('Content seems too promotional - be more authentic');
        score -= 15;
      }
      break;
  }
});

// Check platform limits
Object.entries(limits).forEach(([key, limit]) => {
  if (key === 'caption' && content.length > limit.value) {
    issues.push(`Caption exceeds ${limit.value} ${limit.unit}`);
    score -= 20;
  }
  if (key === 'hashtags') {
    const hashtagCount = (content.match(/#\w+/g) || []).length;
    if (hashtagCount > limit.value) {
      issues.push(`Too many hashtags: ${hashtagCount} (max ${limit.value})`);
      score -= 10;
    }
  }
});

return [{
  json: {
    ...items[0].json,
    quality_score: Math.max(0, score),
    quality_issues: issues,
    passed_quality_check: score >= 70,
    needs_revision: score < 70
  }
}];

// Apply automatic fixes for common issues
const content = items[0].json.formatted_content;
const platform = items[0].json.platform;
const issues = items[0].json.quality_issues || [];
let fixedContent = content;

// Auto-fix based on issues
issues.forEach(issue => {
  if (issue.includes('Caption exceeds')) {
    // Trim to platform limit
    const limit = items[0].json.publish_config.platformLimits.caption?.value || 1000;
    fixedContent = fixedContent.substring(0, limit - 3) + '...';
  }

  if (issue.includes('Too many hashtags')) {
    // Limit hashtags
    const maxHashtags = items[0].json.publish_config.platformLimits.hashtags?.value || 5;
    const hashtags = fixedContent.match(/#\w+/g) || [];
    const limitedHashtags = hashtags.slice(0, maxHashtags);
    // Remove all hashtags and add limited ones at the end
    fixedContent = fixedContent.replace(/#\w+/g, '').trim() + '\n\n' + limitedHashtags.join(' ');
  }

  if (issue.includes('Add more emojis')) {
    // Add relevant emojis
    const emojiMap = {
      'business': '💼',
      'technology': '💻',
      'food': '🍔',
      'fitness': '💪',
      'travel': '✈️',
      'general': '✨'
    };
    const niche = items[0].json.niche || 'general';
    const emoji = emojiMap[niche] || '✨';
    fixedContent = `${emoji} ${fixedContent} ${emoji}`;
  }

  if (issue.includes('Add a question')) {
    // Add engagement question if missing
    if (!fixedContent.includes('?')) {
      fixedContent += '\n\nWhat are your thoughts on this?';
    }
  }

  if (issue.includes('professional language')) {
    // Replace casual words
    fixedContent = fixedContent
      .replace(/\bgonna\b/gi, 'going to')
      .replace(/\bwanna\b/gi, 'want to')
      .replace(/\blol\b/gi, '')
      .replace(/\bomg\b/gi, '')
      .replace(/\bbtw\b/gi, 'by the way');
  }
});

// Re-validate after fixes
const stillHasIssues = fixedContent.length > (items[0].json.publish_config.platformLimits.caption?.value || 10000);

return [{
  json: {
    ...items[0].json,
    formatted_content: fixedContent,
    auto_fixed: true,
    fixes_applied: issues.length,
    ready_to_publish: !stillHasIssues
  }
}];

// Prepare final payload for publishing
const platform = items[0].json.platform;
const content = items[0].json.formatted_content;
const mediaUrl = items[0].json.media_url;
const videoUrl = items[0].json.video_url;
const videoData = items[0].binary?.video;

// Build platform-specific payload
let payload = {};

switch (platform) {
  case 'tiktok':
    payload = {
      caption: content,
      video: videoData || videoUrl,
      thumbnail: items[0].json.thumbnail_url,
      hashtags: (content.match(/#\w+/g) || []).slice(0, 5),
      music_id: items[0].json.trending_audio_id || null,
      privacy: 'public'
    };
    break;

  case 'instagram':
    payload = {
      caption: content,
      media_type: videoUrl ? 'REELS' : 'IMAGE',
      media_url: mediaUrl || videoUrl,
      thumbnail_url: items[0].json.thumbnail_url,
      share_to_feed: true,
      collaborators: [],
      location_id: items[0].json.location_id || null
    };
    break;

  case 'twitter':
    payload = {
      text: content,
      media_ids: mediaUrl ? [items[0].json.media_id] : [],
      reply_settings: 'mentionedUsers'
    };
    break;

  case 'linkedin':
    // LinkedIn uses different format for articles vs posts
    const isArticle = content.length > 1300;
    payload = {
      author: `urn:li:person:${process.env.LINKEDIN_PERSON_ID}`,
      lifecycleState: 'PUBLISHED',
      specificContent: {
        'com.linkedin.ugc.ShareContent': {
          shareCommentary: {
            text: content
          },
          shareMediaCategory: mediaUrl ? 'IMAGE' : 'NONE',
          media: mediaUrl ? [{
            status: 'READY',
            media: mediaUrl
          }] : []
        }
      },
      visibility: {
        'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC'
      }
    };
    break;

  case 'youtube':
    payload = {
      snippet: {
        title: items[0].json.title || content.substring(0, 100),
        description: content,
        tags: (content.match(/#\w+/g) || []).map(tag => tag.substring(1)),
        categoryId: '22' // People & Blogs
      },
      status: {
        privacyStatus: 'public',
        selfDeclaredMadeForKids: false
      }
    };
    break;

  case 'facebook':
    payload = {
      message: content,
      link: items[0].json.link || null,
      picture: mediaUrl || null,
      published: true
    };
    break;

  default:
    payload = {
      content: content,
      media: mediaUrl || videoUrl || null
    };
}

// Add scheduling if specified
if (items[0].json.scheduled_time) {
  payload.scheduled_publish_time = items[0].json.scheduled_time;
  if (platform === 'facebook' || platform === 'instagram') {
    payload.published = false;
  }
}

return [{
  json: {
    ...items[0].json,
    publish_payload: payload,
    platform_endpoint: this.getPlatformEndpoint(platform),
    ready_to_publish: true
  },
  binary: videoData ? { video: videoData } : {}
}];

function getPlatformEndpoint(platform) {
  const endpoints = {
    tiktok: '/tiktok/upload',
    instagram: `https://graph.facebook.com/v12.0/${process.env.INSTAGRAM_ACCOUNT_ID}/media`,
    twitter: 'https://api.twitter.com/2/tweets',
    linkedin: 'https://api.linkedin.com/v2/ugcPosts',
    youtube: 'https://www.googleapis.com/upload/youtube/v3/videos',
    facebook: `https://graph.facebook.com/v12.0/me/feed`
  };
  return endpoints[platform] || '/publish';
}
